class Solution:
    def minOperations(self, nums: List[int], x: int, y: int) -> int:
        d = x - y
        def feasible(t):
            need = 0
            for v in nums:
                rem = v - y * t
                if rem > 0:
                    need += (rem + d - 1) // d
                    if need > t: return False
            return need <= t
        lo, hi = 1, max(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid): hi = mid
            else: lo = mid + 1
        return lo

