class Solution {
public:
    int minOperations(vector<int>& nums, int x, int y) {
        long long d = x - y;
        sort(nums.rbegin(), nums.rend());
        auto feasible = [&](long long t) {
            long long need = 0;
            for (long long v : nums) {
                if (v <= y * t) break;
                need += (v - y * t + d - 1) / d;
                if (need > t) return false;
            }
            return true;
        };
        long long lo = 1, hi = nums[0];
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (feasible(mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
};

