class Solution {
    public int minOperations(int[] nums, int x, int y) {
        long d = x - y;
        nums = Arrays.stream(nums).boxed().sorted(Collections.reverseOrder()).mapToInt(Integer::intValue).toArray();
        long lo = 1, hi = nums[0];
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            long need = 0; boolean ok = true;
            for (long v : nums) {
                if (v <= y * mid) break;
                need += (v - (long) y * mid + d - 1) / d;
                if (need > mid) { ok = false; break; }
            }
            if (ok) hi = mid; else lo = mid + 1;
        }
        return (int) lo;
    }
}

